// The composer is compiled by Vite straight from remotion-composer/src. It is
// typed loosely here so this package's stricter compiler settings are not
// applied to code it does not own.
declare module "@composer/Explainer" {
  import type { ComponentType } from "react";
  export const Explainer: ComponentType<Record<string, unknown>>;
}
declare module "@composer/CinematicRenderer" {
  import type { ComponentType } from "react";
  export const CinematicRenderer: ComponentType<Record<string, unknown>>;
}
